     1→import {DasContextJs} from "@crate-crypto/node-eth-kzg";
     2→import {fromHexString, toHexString} from "@chainsafe/ssz";
     3→import {InputType} from "@lodestar/spec-test-util";
     4→import {TestRunnerFn} from "../utils/types.js";
     5→
     6→const kzg = DasContextJs.create({usePrecomp: true});
     7→
     8→const testFnByType: Record<string, (input: any, output?: any) => any> = {
     9→  blob_to_kzg_commitment: blobToKzgCommitment,
    10→  compute_blob_kzg_proof: computeBlobKzgProof,
    11→  compute_kzg_proof: computeKzgProof,
    12→  verify_blob_kzg_proof: verifyBlobKzgProof,
    13→  verify_blob_kzg_proof_batch: verifyBlobKzgProofBatch,
    14→  verify_kzg_proof: verifyKzgProof,
    15→  compute_cells: computeCells,
    16→  compute_cells_and_kzg_proofs: computeCellsAndKzgProofs,
    17→  recover_cells_and_kzg_proofs: recoverCellsAndKzgProofs,
    18→  verify_cell_kzg_proof_batch: verifyCellKzgProofBatch,
    19→};
    20→
    21→export const kzgTestRunner: TestRunnerFn<KzgTestCase, unknown> = (_fork, testName) => {
    22→  return {
    23→    testFunction: ({data}) => {
    24→      const testFn = testFnByType[testName];
    25→      if (testFn === undefined) {
    26→        throw Error(`Unknown kzg test ${testName}`);
    27→      }
    28→
    29→      return testFn(data.input, data.output);
    30→    },
    31→    options: {
    32→      inputTypes: {data: InputType.YAML},
    33→      getExpected: (testCase) => testCase.data.output,
    34→      // Do not manually skip tests here, do it in packages/beacon-node/test/spec/general/index.test.ts
    35→    },
    36→  };
    37→};
    38→
    39→type KzgTestCase = {
    40→  meta?: any;
    41→  data: {
    42→    input: unknown;
    43→    output: unknown;
    44→  };
    45→};
    46→
    47→type BlobToKzgCommitmentInput = {
    48→  blob: string;
    49→};
    50→function blobToKzgCommitment(input: BlobToKzgCommitmentInput): string | null {
    51→  const blob = fromHexString(input.blob);
    52→  try {
    53→    return toHexString(kzg.blobToKzgCommitment(blob));
    54→  } catch {
    55→    return null;
    56→  }
    57→}
    58→
    59→type ComputeKzgProofInput = {
    60→  blob: string;
    61→  z: string;
    62→};
    63→function computeKzgProof(input: ComputeKzgProofInput): string[] | null {
    64→  const blob = fromHexString(input.blob);
    65→  const z = fromHexString(input.z);
    66→  try {
    67→    const [proof, polynomialResult] = kzg.computeKzgProof(blob, z);
    68→    return [toHexString(proof), toHexString(polynomialResult)];
    69→  } catch {
    70→    return null;
    71→  }
    72→}
    73→
    74→type ComputeBlobKzgProofInput = {
    75→  blob: string;
    76→  commitment: string;
    77→};
    78→function computeBlobKzgProof(input: ComputeBlobKzgProofInput): string | null {
    79→  const blob = fromHexString(input.blob);
    80→  const commitment = fromHexString(input.commitment);
    81→  try {
    82→    return toHexString(kzg.computeBlobKzgProof(blob, commitment));
    83→  } catch {
    84→    return null;
    85→  }
    86→}
    87→
    88→type VerifyKzgProofInput = {
    89→  commitment: string;
    90→  y: string;
    91→  z: string;
    92→  proof: string;
    93→};
    94→function verifyKzgProof(input: VerifyKzgProofInput): boolean | null {
    95→  const commitment = fromHexString(input.commitment);
    96→  const z = fromHexString(input.z);
    97→  const y = fromHexString(input.y);
    98→  const proof = fromHexString(input.proof);
    99→
   100→  try {
   101→    return kzg.verifyKzgProof(commitment, z, y, proof);
   102→  } catch {
   103→    return null;
   104→  }
   105→}
   106→
   107→type VerifyBlobKzgProofInput = {
   108→  blob: string;
   109→  commitment: string;
   110→  proof: string;
   111→};
   112→function verifyBlobKzgProof(input: VerifyBlobKzgProofInput): boolean | null {
   113→  const blob = fromHexString(input.blob);
   114→  const commitment = fromHexString(input.commitment);
   115→  const proof = fromHexString(input.proof);
   116→
   117→  try {
   118→    return kzg.verifyBlobKzgProof(blob, commitment, proof);
   119→  } catch {
   120→    return null;
   121→  }
   122→}
   123→
   124→type VerifyBlobKzgProofBatchInput = {
   125→  blobs: string[];
   126→  commitments: string[];
   127→  proofs: string[];
   128→};
   129→function verifyBlobKzgProofBatch(input: VerifyBlobKzgProofBatchInput): boolean | null {
   130→  const blobs = input.blobs.map(fromHexString);
   131→  const commitments = input.commitments.map(fromHexString);
   132→  const proofs = input.proofs.map(fromHexString);
   133→
   134→  try {
   135→    return kzg.verifyBlobKzgProofBatch(blobs, commitments, proofs);
   136→  } catch {
   137→    return null;
   138→  }
   139→}
