   141→type ComputeCellsInput = {
   142→  blob: string;
   143→};
   144→function computeCells(input: ComputeCellsInput): string[] | null {
   145→  const blob = fromHexString(input.blob);
   146→  try {
   147→    const cells = kzg.computeCells(blob);
   148→    return cells.map(toHexString);
   149→  } catch {
   150→    return null;
   151→  }
   152→}
   153→
   154→type ComputeCellsAndKzgProofsInput = {
   155→  blob: string;
   156→};
   157→function computeCellsAndKzgProofs(input: ComputeCellsAndKzgProofsInput): [string[], string[]] | null {
   158→  const blob = fromHexString(input.blob);
   159→  try {
   160→    const {cells, proofs} = kzg.computeCellsAndKzgProofs(blob);
