   187→type VerifyCellKzgProofBatchInput = {
   188→  commitments: string[];
   189→  cell_indices: number[];
   190→  cells: string[];
   191→  proofs: string[];
   192→};
   193→function verifyCellKzgProofBatch(input: VerifyCellKzgProofBatchInput): boolean | null {
